import CompareClient from './CompareClient';

interface Product {
  id: string;
  name: string;
  price: number;
  category: string;
  rating: number;
  reviews: number;
  inStock: boolean;
}

const PRODUCTS: Product[] = [
  { id: '1', name: 'Premium Headphones', price: 299.99, category: 'Electronics', rating: 4.5, reviews: 1250, inStock: true },
  { id: '2', name: 'Wireless Earbuds', price: 149.99, category: 'Electronics', rating: 4.2, reviews: 3420, inStock: true },
  { id: '3', name: 'Studio Monitor', price: 449.99, category: 'Electronics', rating: 4.8, reviews: 567, inStock: false },
  { id: '4', name: 'Portable Speaker', price: 79.99, category: 'Electronics', rating: 4.0, reviews: 2100, inStock: true },
  { id: '5', name: 'Noise Canceling Pro', price: 379.99, category: 'Electronics', rating: 4.7, reviews: 890, inStock: true },
];

function mean(values: number[]) {
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

function variance(values: number[], meanValue: number) {
  return values.reduce((sum, value) => sum + (value - meanValue) ** 2, 0) / values.length;
}

function medianFromSorted(values: number[]) {
  const mid = Math.floor(values.length / 2);
  if (values.length % 2 === 0) {
    return (values[mid - 1] + values[mid]) / 2;
  }
  return values[mid];
}

function quantileFromSorted(values: number[], quantile: number) {
  const position = (values.length - 1) * quantile;
  const lower = Math.floor(position);
  const upper = Math.ceil(position);
  if (lower === upper) return values[lower];
  return values[lower] + (values[upper] - values[lower]) * (position - lower);
}

export default function ComparePage() {
  const sortedProducts = [...PRODUCTS].sort((a, b) => a.price - b.price);
  const prices = PRODUCTS.map((product) => product.price);
  const ratings = PRODUCTS.map((product) => product.rating);
  const reviews = PRODUCTS.map((product) => product.reviews);

  const sortedPrices = [...prices].sort((a, b) => a - b);
  const sortedRatings = [...ratings].sort((a, b) => a - b);
  const sortedReviews = [...reviews].sort((a, b) => a - b);

  const avgPrice = mean(prices);
  const totalReviews = reviews.reduce((sum, count) => sum + count, 0);
  const bestRated = PRODUCTS.reduce((best, product) => (product.rating > best.rating ? product : best), PRODUCTS[0]);
  const cheapest = PRODUCTS.reduce((best, product) => (product.price < best.price ? product : best), PRODUCTS[0]);

  const priceVariance = variance(prices, avgPrice);
  const ratingMean = mean(ratings);
  const reviewMean = mean(reviews);

  const comparison = {
    avgPrice,
    totalReviews,
    bestRatedName: bestRated.name,
    cheapestName: cheapest.name,
  };

  const advanced = {
    priceStats: {
      mean: avgPrice,
      median: medianFromSorted(sortedPrices),
      std: Math.sqrt(priceVariance),
      variance: priceVariance,
      q1: quantileFromSorted(sortedPrices, 0.25),
      q3: quantileFromSorted(sortedPrices, 0.75),
    },
    ratingStats: {
      mean: ratingMean,
      median: medianFromSorted(sortedRatings),
      std: Math.sqrt(variance(ratings, ratingMean)),
    },
    reviewStats: {
      mean: reviewMean,
      median: medianFromSorted(sortedReviews),
      std: Math.sqrt(variance(reviews, reviewMean)),
